            or item_elements != elements
            or item_regions != regions
            or item_bounds != bounds
        ):
            raise ValueError(
                f"{where} must share the scenarios, elements, regions "
                "and bounds of results[0] in the same order"
            )
        all_data.append(data)

    if not isinstance(minimum, int) or isinstance(minimum, bool):
        raise TypeError("minimum must be a non-bool int")
    if minimum < 1:
        raise ValueError("minimum must be positive")

    total = len(results)
    rows = []
    for scenario_index, scenario in enumerate(scenarios):
        stable = 0
        uncertain = 0
        fragile = 0
        for data in all_data:
            decision = data[scenario_index]["decision"]
            if decision == "stable":
                stable += 1
            elif decision == "uncertain":
                uncertain += 1
            elif decision == "fragile":
                fragile += 1
        valid = stable + uncertain + fragile
        missing = total - valid

        if valid < minimum:
            decision = None
            agreement = None
        else:
            best = max(stable, uncertain, fragile)
            if fragile == best:
                decision = "fragile"
            elif uncertain == best:
                decision = "uncertain"
            else:
                decision = "stable"
            agreement = _round_output(best / valid)

        rows.append(
            {
                "scenario": scenario,
                "valid": valid,
                "missing": missing,
                "votes": [stable, uncertain, fragile],
                "decision": decision,
                "agreement": agreement,
            }
        )

    return {
        "schema": _REGION_WEIGHT_CONSENSUS_SCHEMA,
        "scenarios": list(scenarios),
        "elements": list(elements),
        "regions": list(regions),
        "bounds": list(bounds),
        "data": rows,
    }
